returned: "export function retryPolicy(opts = {}) {
  const { maxAttempts = 1, baseDelayMs = 100, jitter = true } = opts;
  if (!Number.isInteger(maxAttempts) || maxAttempts < 1) throw new Error("maxAttempts must be a positive integer");
  return {
    maxAttempts,
    baseDelayMs,
    jitter,
    delayFor(attempt) {
      if (attempt >= maxAttempts) return null;
      return baseDelayMs * 2 ** attempt;
    },
  };
}
import { test } from "node:test";
import assert from "node:assert/strict";
import { retryPolicy } from "../src/retry.js";

test("delay doubles per attempt", () => {
  const p = retryPolicy({ maxAttempts: 4, baseDelayMs: 10 });
  assert.deepEqual([0, 1, 2, 3, 4].map((a) => p.delayFor(a)), [10, 20, 40, 80, null]);
});

test("rejects zero attempts", () => {
  assert.throws(() => retryPolicy({ maxAttempts: 0 }));
});
